import { connection } from 'next/server';

export default async function Home() {
  // Use connection() to opt out of static prerendering.
  // This tells Next.js that this component depends on dynamic data
  // that is not related to request headers or cookies.
  await connection();

  const timestamp = new Date().toISOString();

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>Current server time: {timestamp}</p>
    </main>
  );
}

